package com.shopsphere;
import java.time.Duration;import org.springframework.beans.factory.annotation.Value;import org.springframework.context.annotation.*;import org.springframework.http.client.JdkClientHttpRequestFactory;import org.springframework.web.client.RestClient;
@Configuration class CartConfig{@Bean ProductPricingGateway pricing(@Value("${shopsphere.product-service-url}")String url,@Value("${shopsphere.http.connect-timeout:2s}")Duration connect,@Value("${shopsphere.http.read-timeout:3s}")Duration read){var client=java.net.http.HttpClient.newBuilder().connectTimeout(connect).build();var f=new JdkClientHttpRequestFactory(client);f.setReadTimeout(read);return new HttpProductPricingGateway(RestClient.builder().baseUrl(url).requestFactory(f).requestInterceptor(CorrelationHeaders.interceptor()).build());}}
